def as_things_stood(apps, schema_editor):
    """Before this, a job had one portrait, and a scene's own place was the newest picture the
    fixing agent's place_edit made for it. Each picture of the presenter in a place was drawn
    from that portrait; each scene keeps its newest own place; and each step takes its scene's
    place, and the portrait when its scene showed the presenter, so nothing made before this
    goes stale by itself."""
    ProducedItem = apps.get_model("jobs", "ProducedItem")
    Scene = apps.get_model("jobs", "Scene")
    SceneStep = apps.get_model("jobs", "SceneStep")

    def portrait_of(job_id):
        return (
            ProducedItem.objects.filter(job_id=job_id, kind="portrait").order_by("version").first()
        )

    for item in ProducedItem.objects.filter(kind__in=["person_in_room", "scene_person_in_room"]):
        item.person = portrait_of(item.job_id)
        item.save(update_fields=["person"])
    for scene in Scene.objects.filter(
        produced__kind__in=["scene_room", "scene_person_in_room"]
    ).distinct():
        scene.place = (
            ProducedItem.objects.filter(
                scene=scene, kind__in=["scene_room", "scene_person_in_room"]
            )
            .order_by("id")
            .last()
        )
        scene.save(update_fields=["place"])
    for step in SceneStep.objects.select_related("scene"):
        step.place_id = step.scene.place_id
        if not step.shows or step.person_shown == "has face":
            step.portrait = portrait_of(step.scene.job_id)
        step.save(update_fields=["place", "portrait"])


